WITH with_latest AS (SELECT s.id, s.rating, top1.brand, top1.product_cost FROM suppliers s LEFT JOIN LATERAL (SELECT c.brand, c.cost AS product_cost FROM products c WHERE c.supplier_id = s.id ORDER BY c.price DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT id, brand, product_cost, CASE WHEN brand RLIKE '^(Globex|Umbrella)$' THEN 'OTHER_ZONE' WHEN brand RLIKE '^(Acme|Initech)$' THEN 'PRIORITY' ELSE 'GROUP_B' END AS brand_zone FROM with_latest ORDER BY brand DESC;
